  sourceRevision: string;
};

type ResultState =
  | { kind: 'idle' }
  | { kind: 'submitting' }
  | {
      kind: 'accepted';
      response: SubmissionResponse;
      correctionContext?: {
        events: SubmissionEvent[];
        fixture: Fixture;
