                <p>
                  <code>{detail.code}</code>
                  {detail.field ? (
                    <>
                      {' Â· '}
                      <code>{detail.field}</code>
                    </>
                  ) : null}
                </p>
                {formatApiValidationMessage(detail) !== detail.message ? (
                  <p>{detail.message}</p>
                ) : null}
              </details>
            </li>
          ))}
        </ol>
      ) : null}
    </div>
