}

function SubmissionWorkflowSelector({
  value,
  onChange,
}: {
  value: SubmissionWorkflow;
  onChange: (workflow: SubmissionWorkflow) => void;
}) {
  type Option = { value: SubmissionWorkflow; label: string; description: string };

  const guidedOptions: Option[] = [
