import type { ReactNode } from 'react';
import { Link } from 'react-router-dom';

interface DetailLayoutProps {
  backLabel: string;
  backTo: string;
  children: ReactNode;
  eyebrow: string;
  title: string;
}

export function DetailLayout({ backLabel, backTo, children, eyebrow, title }: DetailLayoutProps) {
  return (
    <article className="detail-page content-boundary">
      <Link className="back-link" to={backTo}>
        Back to {backLabel}
      </Link>
      <header className="page-heading page-heading--detail">
        <p className="eyebrow">{eyebrow}</p>
        <h1>{title}</h1>
      </header>
      {children}
    </article>
  );
}

export function DetailLoading({ label }: { label: string }) {
  return (
    <div className="state-message state-message--detail" role="status">
      <h1>Loading {label}</h1>
      <p>The published record is being requested from the Sport Analytics API.</p>
    </div>
  );
}

export function DetailError({
  error,
  label,
  reload,
}: {
  error: Error;
  label: string;
  reload(): void;
}) {
  return (
    <div className="state-message state-message--detail state-message--error" role="alert">
      <h1>{label} could not be loaded</h1>
      <p>{error.message}</p>
      <button className="button button--secondary" onClick={reload} type="button">
        Try again
      </button>
    </div>
  );
}

export function RecordFacts({ children }: { children: ReactNode }) {
  return <dl className="record-facts">{children}</dl>;
}

export function RecordFact({ label, value }: { label: string; value: ReactNode }) {
  return (
    <div>
      <dt>{label}</dt>
      <dd>{value}</dd>
    </div>
  );
}

export function RelatedLinks({ children }: { children: ReactNode }) {
  return (
    <nav aria-labelledby="related-records-heading" className="related-records">
      <h2 id="related-records-heading">Related records</h2>
      <div>{children}</div>
    </nav>
  );
}

import type { AuthChangeEvent, Session, User } from '@supabase/supabase-js';
import { act, fireEvent, render, screen, within } from '@testing-library/react';
import type { ComponentProps } from 'react';
import { MemoryRouter } from 'react-router-dom';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import App from './App';
import { AuthProvider } from './features/auth/AuthProvider';
import { THEME_STORAGE_KEY } from './theme';

const testApiBaseUrl = import.meta.env.VITE_API_BASE_URL ?? 'http://localhost:3000/api/v1';

type AuthClient = ComponentProps<typeof AuthProvider>['client'];
type AuthStateListener = (event: AuthChangeEvent, session: Session | null) => void;

function createSession(): Session {
  const user = {
    id: 'user-123',
    aud: 'authenticated',
    role: 'authenticated',
    email: 'person@example.com',
    app_metadata: {},
    user_metadata: {},
    identities: [],
    created_at: '2026-08-09T00:00:00.000Z',
  } satisfies User;

  return {
    access_token: 'current-access-token',
    refresh_token: 'managed-by-supabase',
    expires_in: 3600,
    token_type: 'bearer',
    user,
  };
}

function currentUserResponse(approvalState: 'not_requested' | 'pending' | 'approved' | 'rejected') {
  return {
    ok: true,
    status: 200,
    json: vi.fn().mockResolvedValue({
      user: {
        id: '17',
        subject: 'user-123',
        displayName: 'Example User',
        role: 'viewer',
        approvalState,
        requestedCompetition: null,
        competitionIds: approvalState === 'approved' ? ['5'] : [],
      },
    }),
  } as unknown as Response;
}

function competitionsResponse() {
  return apiResponse(200, {
    data: [{ competitionId: '5', name: 'Premier T20' }],
    pagination: { nextCursor: null },
  });
}

function accountPageFetch(approvalState: 'not_requested' | 'pending' | 'approved' | 'rejected') {
  return vi.fn().mockImplementation((input: RequestInfo | URL) => {
    const path = new URL(String(input)).pathname;

    if (path.endsWith('/auth/me')) {
      return Promise.resolve(currentUserResponse(approvalState));
    }

    if (path.endsWith('/competitions')) {
      return Promise.resolve(competitionsResponse());
    }

    throw new Error(`Unexpected request: ${path}`);
  });
}

function createAuthClient(session: Session | null) {
  let listener: AuthStateListener | undefined;
  const client = {
    getSession: vi.fn().mockResolvedValue({ data: { session } }),
    onAuthStateChange: vi.fn((nextListener: AuthStateListener) => {
      listener = nextListener;
      return {
        data: {
          subscription: {
            id: 'app-test-subscription',
            callback: nextListener,
            unsubscribe: vi.fn(),
          },
        },
      };
    }),
    signInWithOAuth: vi
      .fn()
      .mockResolvedValue({ data: { provider: 'google', url: null }, error: null }),
    signOut: vi.fn().mockResolvedValue({ error: null }),
  } as unknown as AuthClient;

  return {
    client,
    emit(event: AuthChangeEvent, nextSession: Session | null) {
      listener?.(event, nextSession);
    },
  };
}

function apiResponse(status: number, body: unknown): Response {
  return {
    ok: status >= 200 && status < 300,
    status,
    json: vi.fn().mockResolvedValue(body),
  } as unknown as Response;
}

function renderApp(path = '/', session: Session | null = null) {
  const auth = createAuthClient(session);

  render(
    <AuthProvider client={auth.client}>
      <MemoryRouter initialEntries={[path]}>
        <App />
      </MemoryRouter>
    </AuthProvider>,
  );

  return auth;
}

function useSystemTheme(prefersDark: boolean) {
  vi.stubGlobal(
    'matchMedia',
    vi.fn().mockImplementation((query: string) => ({
      matches: query === '(prefers-color-scheme: dark)' && prefersDark,
      media: query,
      onchange: null,
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      addListener: vi.fn(),
      removeListener: vi.fn(),
      dispatchEvent: vi.fn(),
    })),
  );
}

