          </label>
          <textarea
            id="review-reason"
            maxLength={2000}
            value={reason}
            onChange={(event) => setReason(event.target.value)}
            disabled={saving}
          />
          <div className="batch-review__actions">
            <button
              className="button button--primary"
              type="button"
              disabled={saving || report.reviewSummary.approvalBlocked}
              onClick={(event) => begin('approved', event.currentTarget)}
            >
              Approve and publish
            </button>
            <button
              className="button button--secondary"
              type="button"
              disabled={saving}
              onClick={(event) => begin('returned_for_correction', event.currentTarget)}
            >
              Return for correction
            </button>
            <button
              className="button button--danger"
              type="button"
              disabled={saving}
              onClick={(event) => begin('rejected', event.currentTarget)}
            >
              Reject batch
            </button>
          </div>
        </section>
      ) : (
        <p>
          This batch is no longer awaiting a decision. Duplicate or competing actions are not
          submitted.
        </p>
      )}
      {feedback ? (
        <p role="status" aria-live="polite">
          {feedback}
        </p>
      ) : null}
      {pending ? (
        <ConfirmationDialog
          decision={pending}
          reason={reason.trim()}
          saving={saving}
          onCancel={cancel}
          onConfirm={() => void confirm()}
        />
      ) : null}
    </ReviewerGate>
  );
}

