@media (max-width: 56.25rem) {
  .site-header__inner {
    min-height: 4.75rem;
    grid-template-columns: minmax(0, 1fr) auto;
    padding-block: 0.5rem;
  }

  .site-navigation,
  .auth-navigation {
    display: none;
  }

  .site-header__controls {
    width: auto;
    gap: 0.75rem;
  }

  .mobile-navigation {
    position: static;
    display: block;
  }

  .mobile-navigation__toggle {
    color: var(--colour-text);
  }

  .mobile-navigation__panel {
    position: absolute;
    top: 100%;
    right: 0;
    left: 0;
    z-index: 30;
    max-height: calc(100vh - 4.75rem);
    padding: 1rem max(1rem, calc((100vw - 52rem) / 2));
    border-block: 1px solid var(--colour-border);
    background: var(--colour-surface);
    box-shadow: var(--shadow-header);
    overflow-y: auto;
  }

  .mobile-navigation__panel nav {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 1.5rem;
  }

  .mobile-navigation__panel section {
    display: grid;
    align-content: start;
    gap: 0.25rem;
  }

  .mobile-navigation__panel h2 {
    margin: 0 0 0.5rem;
    color: var(--colour-text-muted);
    font-family: var(--font-body);
    font-size: 0.75rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  .mobile-navigation__panel a,
  .mobile-navigation__panel button {
    min-height: 2.75rem;
    display: flex;
    align-items: center;
    padding: 0.625rem 0.75rem;
    border: 0;
    border-radius: 6px;
    background: transparent;
    color: var(--colour-text);
    font: inherit;
    font-weight: 600;
    text-align: left;
    text-decoration: none;
  }

  .mobile-navigation__panel a:hover,
  .mobile-navigation__panel a.active,
  .mobile-navigation__panel button:hover {
    background: var(--colour-primary-soft);
  }
}

@media (max-width: 39.9375rem) {
  .site-header__inner {
