.navigation-menu {
  position: relative;
}

.navigation-menu > button,
.mobile-navigation__toggle {
  min-height: 2.75rem;
  padding: 0.625rem 0.75rem;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  color: var(--colour-text-secondary);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.navigation-menu > button:hover,
.navigation-menu > button[aria-expanded='true'],
.mobile-navigation__toggle:hover,
.mobile-navigation__toggle[aria-expanded='true'] {
  border-color: var(--colour-border);
  background: var(--colour-surface-raised);
  color: var(--colour-text);
}

.navigation-menu__panel {
  position: absolute;
  top: calc(100% + 0.25rem);
  left: 0;
  z-index: 20;
  display: grid;
  min-width: 12rem;
  padding: 0.5rem;
  border: 1px solid var(--colour-border);
  border-radius: 10px;
  background: var(--colour-surface);
  box-shadow: var(--shadow-header);
}

.navigation-menu__panel a {
  padding: 0.75rem;
  border-radius: 6px;
  color: var(--colour-text);
  text-decoration: none;
}

.navigation-menu__panel a:hover,
.navigation-menu__panel a.active {
  background: var(--colour-primary-soft);
}

.mobile-navigation {
  display: none;
}

.breadcrumbs {
  margin-block: var(--space-6) var(--space-4);
  overflow-x: auto;
}

