import type { ApplicationRole, SubmitterApprovalState } from '@sport-analytics/contracts';
import type { AuthChangeEvent, Session, User } from '@supabase/supabase-js';
import { act, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import type { ComponentProps } from 'react';
import { MemoryRouter } from 'react-router-dom';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { PublicApp } from '../../App';
import { AuthProvider } from '../auth/AuthProvider';

type AuthClient = ComponentProps<typeof AuthProvider>['client'];
type AuthStateListener = (event: AuthChangeEvent, session: Session | null) => void;

function jsonResponse(status: number, body: unknown): Response {
  return {
    ok: status >= 200 && status < 300,
    status,
    json: vi.fn().mockResolvedValue(body),
  } as unknown as Response;
}

function createSession(): Session {
  const user = {
    id: 'requesting-user',
    aud: 'authenticated',
    role: 'authenticated',
    email: 'viewer@example.com',
    app_metadata: {},
    user_metadata: {},
    identities: [],
    created_at: '2026-08-16T00:00:00.000Z',
  } satisfies User;

  return {
    access_token: 'viewer-access-token',
    refresh_token: 'managed-by-supabase',
    expires_in: 3600,
    token_type: 'bearer',
    user,
  };
}

function createAuthClient(session: Session | null = createSession()) {
  return {
    getSession: vi.fn().mockResolvedValue({ data: { session } }),
    onAuthStateChange: vi.fn((listener: AuthStateListener) => ({
      data: {
        subscription: {
          id: 'submitter-access-test-subscription',
          callback: listener,
          unsubscribe: vi.fn(),
        },
      },
    })),
    signInWithOAuth: vi
      .fn()
      .mockResolvedValue({ data: { provider: 'google', url: null }, error: null }),
    signOut: vi.fn().mockResolvedValue({ error: null }),
  } as unknown as AuthClient;
}

function currentUser(
  approvalState: SubmitterApprovalState,
  role: ApplicationRole = 'viewer',
  requestedCompetition = approvalState === 'not_requested'
    ? null
    : { competitionId: '5', name: 'Premier T20' },
): Response {
  return jsonResponse(200, {
    user: {
      id: '17',
      subject: 'requesting-user',
      displayName: 'Requesting User',
      role,
      approvalState,
      requestedCompetition,
      competitionIds: role === 'submitter' || role === 'admin' ? ['5'] : [],
    },
  });
}

function competitionsResponse(
  competitions = [
    { competitionId: '5', name: 'Premier T20' },
    { competitionId: '8', name: 'University League' },
  ],
): Response {
  return jsonResponse(200, {
    data: competitions,
    pagination: { nextCursor: null },
  });
}

function renderAccountPage(session: Session | null = createSession()) {
  return render(
    <AuthProvider client={createAuthClient(session)}>
      <MemoryRouter initialEntries={['/account/access']}>
        <PublicApp />
      </MemoryRouter>
    </AuthProvider>,
  );
}

function useSystemTheme() {
  vi.stubGlobal(
    'matchMedia',
    vi.fn().mockImplementation((query: string) => ({
      matches: false,
      media: query,
      onchange: null,
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      addListener: vi.fn(),
      removeListener: vi.fn(),
      dispatchEvent: vi.fn(),
    })),
  );
}

describe('submitter access request and status interface', () => {
  beforeEach(() => {
    window.localStorage.clear();
    useSystemTheme();
  });

  afterEach(() => {
    vi.restoreAllMocks();
    vi.unstubAllGlobals();
  });

  it('does not load application account data while signed out', async () => {
    const fetchMock = vi.fn();
    vi.stubGlobal('fetch', fetchMock);

    renderAccountPage(null);

    expect(await screen.findByText(/you are signed out/i)).toBeInTheDocument();
    expect(screen.queryByRole('heading', { name: 'Submitter access' })).not.toBeInTheDocument();
    expect(fetchMock).not.toHaveBeenCalled();
  });

  it('submits an eligible request, exposes progress, and reloads the persisted pending state', async () => {
    let approvalState: SubmitterApprovalState = 'not_requested';
    let requestedCompetition: { competitionId: string; name: string } | null = null;
    let resolveRequest!: (response: Response) => void;
    const pendingRequest = new Promise<Response>((resolve) => {
      resolveRequest = resolve;
    });
    const fetchMock = vi.fn().mockImplementation((input: RequestInfo | URL) => {
      const path = new URL(String(input)).pathname;

      if (path.endsWith('/auth/me')) {
        return Promise.resolve(currentUser(approvalState, 'viewer', requestedCompetition));
      }

      if (path.endsWith('/competitions')) {
        return Promise.resolve(competitionsResponse());
      }

      if (path.endsWith('/submitter-access-requests')) {
        return pendingRequest;
      }

      throw new Error(`Unexpected request: ${path}`);
    });
    vi.stubGlobal('fetch', fetchMock);

    renderAccountPage();

    const competitionSelect = await screen.findByRole('combobox', { name: 'Competition' });
    expect(competitionSelect).toHaveValue('5');
    fireEvent.change(competitionSelect, { target: { value: '8' } });
    fireEvent.click(await screen.findByRole('button', { name: 'Request submitter access' }));

    expect(screen.getByRole('button', { name: 'Requesting accessâ€¦' })).toBeDisabled();

    approvalState = 'pending';
    requestedCompetition = { competitionId: '8', name: 'University League' };
    await act(async () => {
      resolveRequest(
        jsonResponse(201, {
          data: {
            accountId: '17',
            approvalState: 'pending',
            requestedCompetition: { competitionId: '8', name: 'University League' },
          },
        }),
      );
    });

    expect(await screen.findByText('Pending approval')).toBeInTheDocument();
        <p className="auth-error" role="alert">
          We could not complete sign-in. Please try again.
        </p>
        <CallbackRecoveryLinks />
      </>
    );
  } else if (isLoading) {
    callbackContent = <p role="status">Completing sign-inâ€¦</p>;
  } else if (isAuthenticated) {
    callbackContent = <p role="status">Sign-in complete. Opening your accountâ€¦</p>;
  } else {
    callbackContent = (
      <>
        <p className="auth-error" role="alert">
          We could not establish a signed-in session. Please try again.
        </p>
        <CallbackRecoveryLinks />
      </>
    );
  }

  return (
    <section className="auth-page content-boundary" aria-labelledby="auth-callback-title">
      <div className="auth-card">
        <p className="eyebrow">Supabase managed authentication</p>
        <h1 id="auth-callback-title">Completing Sign In</h1>
        {callbackContent}
      </div>
    </section>
  );
}

function AccountOverview({ identityEmail }: { identityEmail: string | undefined }) {
  const client = useAuthenticatedApiClient();
  const [profile, setProfile] = useState<CurrentUserProfile | null>(null);
  const [error, setError] = useState(false);

  useEffect(() => {
    const controller = new AbortController();
    void getCurrentUserProfile(client, controller.signal)
      .then(setProfile)
      .catch(() => {
        if (!controller.signal.aborted) setError(true);
      });
    return () => controller.abort();
  }, [client]);

  if (error) return <p role="alert">Your account summary could not be loaded.</p>;
  if (!profile) return <p role="status">Loading account summaryÃ¢â‚¬Â¦</p>;

  return (
    <section aria-labelledby="account-overview-title">
      <h2 id="account-overview-title">Overview</h2>
      <dl className="identity-details">
        <div><dt>Email</dt><dd>{identityEmail ?? 'Not available'}</dd></div>
        <div><dt>Role</dt><dd>{profile.role}</dd></div>
        <div><dt>Submission access</dt><dd>{profile.approvalState.replaceAll('_', ' ')}</dd></div>
        {profile.competitionIds.length > 0 ? (
          <div><dt>Competition scopes</dt><dd>{profile.competitionIds.length}</dd></div>
        ) : null}
      </dl>
    </section>
  );
}

function AccountSignOutAction() {
  const { signOut } = useAuth();
  const navigate = useNavigate();
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(false);
  async function handleSignOut() {
    setBusy(true); setError(false);
    try { await signOut(); navigate('/', { replace: true }); }
    catch { setError(true); setBusy(false); }
  }
  return (
    <section aria-labelledby="sign-out-title">
      <h2 id="sign-out-title">Sign out</h2>
      <p>End your managed session on this device. Public browsing remains available.</p>
      <button className="button button--secondary" type="button" disabled={busy} onClick={() => void handleSignOut()}>
        {busy ? 'Signing Out\u2026' : 'Sign out'}
      </button>
      {error ? <p role="alert">We could not sign you out. Please try again.</p> : null}
    </section>
  );
}

export function AccountPage() {
  const { identity, isAuthenticated, isLoading } = useAuth();
  const { section = 'overview' } = useParams();
  const activeSection = ['overview', 'access', 'security'].includes(section) ? section : 'overview';

  usePageTitle('Account');

  return (
    <section className="auth-page account-page content-boundary" aria-labelledby="account-page-title">
      <Breadcrumbs items={[{ label: 'Account', to: `/account/${activeSection}` }]} />
      <div className="auth-card">
        <p className="eyebrow">Identity and access</p>
        <h1 id="account-page-title">Account</h1>
        {isLoading ? (
          <p role="status">Loading accountâ€¦</p>
        ) : isAuthenticated && identity ? (
          <>
            <LocalNavigation label="Account sections" items={[
              { label: 'Overview', to: '/account/overview' },
              { label: 'Access', to: '/account/access' },
              { label: 'Security', to: '/account/security' },
            ]} />
            {activeSection === 'overview' ? <AccountOverview identityEmail={identity.email} /> : null}
            {activeSection === 'access' ? <SubmitterAccessPanel /> : null}
            {activeSection === 'security' ? <><AccountSignOutAction /><AccountDeletionForm /></> : null}
          </>
        ) : (
          <p>
            You are signed out. <Link to="/sign-in">Login or Sign up</Link> to view your account.
          </p>
        )}
      </div>
    </section>
  );
}

