export function ThemeToggle() {
  const [theme, setTheme] = useState<Theme>(getInitialTheme);
  const isNightMatch = theme === 'night';
  const nextThemeName = isNightMatch ? 'Day Match' : 'Night Match';

  useLayoutEffect(() => {
    applyTheme(theme);
  }, [theme]);

  function handleThemeChange() {
